public int minTime(int n, int[][] edges, boolean[] hasApple) {
    int[] time = new int[n];
    Arrays.fill(time, Integer.MAX_VALUE);
    time[0] = 0;

    // BFS to calculate the minimum time to reach each node
    for (int i = 0; i < n; i++) {
        for (int[] edge : edges) {
            int from = edge[0], to = edge[1];
            time[to] = Math.min(time[to], time[from] + 1);
        }
    }

    // Calculate the total time required to collect the apples
    int totalTime = 0;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            totalTime += time[i];
        }
    }

    return totalTime;
}

public String sortString(String s) {
    List<Character> characters = new ArrayList<>();
    for (char c : s.toCharArray()) {
        characters.add(c);
    }
    // Sort the characters in ascending order
    Collections.sort(characters);
    StringBuilder result = new StringBuilder();
    // Step 1: Add smallest character
    result.append(characters.get(0));
    // Step 2: Add smallest character that is greater than the last appended character
    for (int i = 1; i < characters.size(); i++) {
        if (characters.get(i) > result.charAt(result.length() - 1)) {
            result.append(characters.get(i));
        }
    }
    // Step 3: Add largest character
    result.append(characters.get(characters.size() - 1));
    // Step 4: Add largest character that is smaller than the last appended character
    for (int i = characters.size() - 2; i >= 0; i--) {
        if (characters.get(i) < result.charAt(result.length() - 1)) {
            result.append(characters.get(i));
        }
    }
    return result.toString();
}

