public int minCostClimbingStairs(int[] cost){
  // Special case: if the array has only one element,
  // return the element as the minimum cost.
  if (cost.length == 1) {
    return cost[0];
  }
  // Initialize two variables to store the minimum cost of
  // climbing the stairs.
  var cost1 = 0;
  var cost2 = 0;
  // Iterate through the array.
  for (var i = 0; i < cost.length; i++) {
    // Calculate the cost of climbing the stairs from the current step.
    cost1 = Math.min(cost1, cost2) + cost[i];
    // Update the cost2 variable.
    cost2 = cost1 - cost[i];
  }
  // Return the minimum cost.
  return Math.min(cost1, cost2);
}

