public static boolean isPowerOfTwo(int n) {
    /*
     * Base Case: if n is 1, return true.
     * If n is 0 or negative, return false.
     */
    if (n == 1) {
        return true;
    } else if (n <= 0) {
        return false;
    }

    /*
     * Recursive Case: if n is odd, return false.
     * If n is even, divide it by 2 and pass the result to the recursive call.
     */
    if (n % 2 != 0) {
        return false;
    } else {
        return isPowerOfTwo(n / 2);
    }
}

