public static int squarePermutations(int[] A) {
    int n = A.length;
    int[] dp = new int[n];
    Arrays.fill(dp, 1);
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (Math.sqrt(A[i] + A[j]) % 1 == 0) {
                dp[i] += dp[j];
            }
        }
    }
    return dp[n - 1];
}

