    int[] result = new int[n * m];
    int i = 0;
    for (int k = 0; k < Math.min(n, m); k++) {
        int top = k;
        int bottom = n - k - 1;
        for (int j = k; j < m - k; j++) {
            result[i++] = mat[top--][j];
        }
        for (int j = k + 1; j < m - k; j++) {
            result[i++] = mat[bottom--][j];
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
