public static int calculateUniqueSum(int[] nums) {
    Set<Integer> unique = new HashSet<>();
    for (int num : nums) {
        unique.add(num);
    }
    int sum = 0;
    for (int num : unique) {
        sum += num;
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        count++;
        n -= i * i;
    }
    return count;
}

